"""Chapter 6: Methodology and Software Implementation for FINJARVIS.

methodology_blocks() is also rendered (renumbered) by document 9, application_blocks() by document 12; blocks() is the report chapter.
Numbers come from facts.py (experiments/metrics.json); formulas and parameters are exactly what ml/*.py, services/*.py and backend/main.py compute.
"""

import os
import textwrap

from . import facts as F
from .blocks import B, CODE as _CODE, EQ, FIG, H1, H2, H3, N, P, TAB
from .refs import N as cite


def _wrap(text, width=110):
    out = []
    for line in text.split("\n"):
        if len(line) <= width:
            out.append(line)
        else:
            indent = len(line) - len(line.lstrip())
            out.extend(textwrap.wrap(line, width, subsequent_indent=" " * (indent + 4), break_long_words=False) or [line])
    return "\n".join(out)


def CODE(text, size=8.5):
    return _CODE(_wrap(text, 110), size)


_DG = {
    "cat": ("11_categoriser_pipeline.png", "Categoriser pipeline: description, TF-IDF, logistic regression, label, optional correction and retraining."),
    "health": ("12_health_score_model.png", "Financial health score model: six weighted components, clipped sum, rating band."),
    "algo": ("10_flowchart_algorithm.png", "Flowchart of the core algorithms: categoriser, forecast, health score and budget alerts."),
}


def _dg(key, caption=None, width=5.4):
    f, cap = _DG[key]
    path = F.diag(f)
    return [FIG(path, caption or cap, width)] if os.path.exists(path) else []


def _fg(name, caption, width=5.6):
    path = F.fig(name)
    return [FIG(path, caption, width)] if os.path.exists(path) else []


