               ["Classifier", "`LogisticRegression(max_iter=1000)`; default C = 1, lbfgs, multinomial"],
               ["Training data", "51 seed pairs; on a correction: seed + the user's whole history + the corrected pair"],
               ["Persistence", "One pickle file for all users (`ml/expense_model.pkl`, ignored by git)"],
               ["Fallback", "Keyword table, then 'Other'; the model itself never outputs 'Other'"],
